/*
 * Persistent Bank — RuneLite plugin
 *
 * In-memory mutable state for one Jagex account. The plugin keeps a map of
 * accountHash -> AccountState so different accounts on the same launcher
 * don't clobber each other during account hopping.
 *
 * This is a plain data holder; serialization and the rate-limiter live in
 * SnapshotWriter and PersistentBankPlugin respectively.
 */
package com.persistentbank;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledFuture;

class AccountState
{
	/** Stable Jagex account identifier. Key of the per-account map. */
	final long accountHash;

	/** In-game display name captured at last snapshot. Used as a UX hint
	 *  for the RSVault rename flow — the accountHash remains the source
	 *  of truth. */
	String displayName;

	/** Per-section last-observed data. Each is nullable: null means
	 *  "the plugin hasn't observed this container yet since the client
	 *  started". We never clobber a populated section with null. */
	List<ContainerItem> bank;
	long bankUpdatedAt;

	List<ContainerItem> inventory;
	long inventoryUpdatedAt;

	List<EquipmentItem> equipment;
	long equipmentUpdatedAt;

	List<ContainerItem> seedVault;
	long seedVaultUpdatedAt;

	List<GeSlot> grandExchange;
	long geUpdatedAt;

	/** Rate-limiter state. */
	long lastWriteMs;
	/** Epoch ms of the last appended wealth-history point (login-burst throttle). */
	long lastHistoryMs;
	/** Value (gp) of the last appended history point; used to detect a collapse. */
	long lastHistoryValue;
	/** A suspiciously-low total held back until a second reading corroborates it
	 *  (0 = none pending). Stops a one-off bad capture entering history without
	 *  freezing a genuine sustained drop. */
	long pendingLowValue;
	boolean dirty;

	/** Reference to a pending deferred-flush so we can cancel/coalesce. */
	ScheduledFuture<?> pendingFlush;

	/** Have we ever successfully written this account to disk? Used so we
	 *  can short-circuit the cooldown for brand-new accounts (first-snapshot
	 *  immediate). */
	boolean hasWrittenOnce;

	/** Wall-clock ms at which this account was first seen (i.e. the moment
	 *  we fired the first-sight flush). Used to open a short grace window
	 *  during which every event flushes immediately, so the login burst
	 *  (GE -> inventory -> equipment -> seed vault, plus the display name
	 *  showing up once the player spawns) all land on disk instead of
	 *  getting swallowed by the rate limiter. */
	long firstSeenAtMs;

	/** Per-section GE-value totals, recomputed at every write using the
	 *  current ItemManager price map. These are denormalized into the JSON
	 *  so the Wealth panel (and any external reader) can show a wealth
	 *  breakdown without iterating items or doing its own price lookups.
	 *  Zero means "no data yet" — consumers should treat a missing section
	 *  the same as a zero-valued section. */
	long bankValueGp;
	long inventoryValueGp;
	long equipmentValueGp;
	long seedVaultValueGp;
	long geValueGp;

	/** Sum of the five section values above. Convenience for the panel's
	 *  grand-total row and for external readers that don't want to sum
	 *  the sections themselves. */
	long totalValueGp;
	/** True when the last write saw every enabled wealth section (or hydrated it):
	 *  a complete, trustworthy net worth. False = a section (usually the bank) has
	 *  not been observed yet, so the total is partial and must not be shown as wealth. */
	boolean complete;

	AccountState(long accountHash)
	{
		this.accountHash = accountHash;
	}

	/** Mark a section as dirty. Caller decides whether to flush now or defer. */
	void touch() { this.dirty = true; }

	// ---- plain-data value types --------------------------------------------

	static class ContainerItem
	{
		final int id;
		final int qty;
		final boolean noted;

		ContainerItem(int id, int qty, boolean noted)
		{
			this.id = id;
			this.qty = qty;
			this.noted = noted;
		}
	}

	static class EquipmentItem extends ContainerItem
	{
		final String slot;

		EquipmentItem(int id, int qty, String slot)
		{
			super(id, qty, false);
			this.slot = slot;
		}
	}

	static class GeSlot
	{
		final int slot;
		final String state;
		final Integer itemId;
		final Integer qtySought;
		final Integer qtyTraded;
		final Integer pricePer;
		final Integer spent;

		GeSlot(int slot, String state, Integer itemId, Integer qtySought,
			   Integer qtyTraded, Integer pricePer, Integer spent)
		{
			this.slot = slot;
			this.state = state;
			this.itemId = itemId;
			this.qtySought = qtySought;
			this.qtyTraded = qtyTraded;
			this.pricePer = pricePer;
			this.spent = spent;
		}

		static GeSlot empty(int slot)
		{
			return new GeSlot(slot, "EMPTY", null, null, null, null, null);
		}
	}

	/** Convenience: copy a source list, keeping it detached from any live
	 *  game object we might have read from. */
	static <T> List<T> snapshotList(List<T> src)
	{
		return src == null ? null : new ArrayList<>(src);
	}
}

/*
 * Persistent Bank — RuneLite plugin
 *
 * Config surface exposed in the RuneLite sidebar. All options default to ON
 * (snapshot everything) because the intent of installing the plugin is to
 * have a complete picture; individual sections are toggleable for people
 * who want to narrow the footprint.
 */
package com.persistentbank;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("persistentbank")
public interface PersistentBankConfig extends Config
{
	@ConfigSection(
		name = "What to snapshot",
		description = "Pick which containers are included in each snapshot.",
		position = 0
	)
	String sectionWhat = "what";

	@ConfigSection(
		name = "Snapshot cadence",
		description = "How often snapshots get written to disk.",
		position = 1
	)
	String sectionCadence = "cadence";

	@ConfigSection(
		name = "Advanced",
		description = "Paths and debug options.",
		position = 2
	)
	String sectionAdvanced = "advanced";

	// ---- What to snapshot --------------------------------------------------

	@ConfigItem(
		keyName = "snapshotBank",
		name = "Bank",
		description = "Include bank contents in snapshots.",
		section = sectionWhat,
		position = 0
	)
	default boolean snapshotBank() { return true; }

	@ConfigItem(
		keyName = "snapshotInventory",
		name = "Inventory",
		description = "Include the 28-slot inventory in snapshots.",
		section = sectionWhat,
		position = 1
	)
	default boolean snapshotInventory() { return true; }

	@ConfigItem(
		keyName = "snapshotEquipment",
		name = "Equipment",
		description = "Include currently-worn gear in snapshots.",
		section = sectionWhat,
		position = 2
	)
	default boolean snapshotEquipment() { return true; }

	@ConfigItem(
		keyName = "snapshotSeedVault",
		name = "Seed vault",
		description = "Include the farming guild seed vault in snapshots.",
		section = sectionWhat,
		position = 3
	)
	default boolean snapshotSeedVault() { return true; }

	@ConfigItem(
		keyName = "snapshotGrandExchange",
		name = "Grand Exchange",
		description = "Include open/completed GE slots in snapshots.",
		section = sectionWhat,
		position = 4
	)
	default boolean snapshotGrandExchange() { return true; }

	// ---- Cadence -----------------------------------------------------------

	@Range(min = 1, max = 120)
	@ConfigItem(
		keyName = "minMinutesBetweenWrites",
		name = "Minimum minutes between snapshots",
		description =
			"Rate-limit writes per account. A change triggers an immediate write if this much time " +
				"has passed since the last one; otherwise the write is deferred until the cooldown expires.",
		section = sectionCadence,
		position = 0
	)
	default int minMinutesBetweenWrites() { return 15; }

	@ConfigItem(
		keyName = "flushOnLogout",
		name = "Flush on logout",
		description =
			"When you log out, flush any unwritten changes immediately instead of waiting for the " +
				"cooldown. Recommended ON so short sessions still produce a snapshot.",
		section = sectionCadence,
		position = 1
	)
	default boolean flushOnLogout() { return true; }

	@ConfigItem(
		keyName = "firstSnapshotImmediate",
		name = "First snapshot immediate",
		description =
			"When the plugin sees a new account for the first time, write a snapshot immediately " +
				"instead of waiting for the cooldown.",
		section = sectionCadence,
		position = 2
	)
	default boolean firstSnapshotImmediate() { return true; }

	// ---- Advanced ----------------------------------------------------------

	@ConfigItem(
		keyName = "snapshotDirOverride",
		name = "Snapshot folder (override)",
		description =
			"Leave blank to use the default: <RuneLite dir>/persistent-bank. Set to an absolute path to " +
				"write elsewhere (e.g. a folder RSVault is watching).",
		section = sectionAdvanced,
		position = 0
	)
	default String snapshotDirOverride() { return ""; }

	@ConfigItem(
		keyName = "verboseLogging",
		name = "Verbose logging",
		description = "Log every write to the RuneLite log. Useful when diagnosing why a snapshot isn't landing.",
		section = sectionAdvanced,
		position = 1
	)
	default boolean verboseLogging() { return false; }
}

/*
 * Persistent Bank — RuneLite plugin
 *
 * Snapshots the player's bank / inventory / equipment / seed vault / GE slots
 * to disk on a rate-limited cadence. Another application (RSVault) watches the
 * output folder and aggregates snapshots across every Jagex account the user
 * has logged into.
 *
 * Compliance posture: strictly observational. We read from Client, we write
 * JSON to disk, we do nothing that changes game behavior. No input synthesis,
 * no packet modification, no automation.
 *
 * Rate limiter: per accountHash we track lastWriteMs. An event fires, we mark
 * the account dirty. If (now - lastWriteMs) >= cooldown, we write immediately;
 * otherwise we schedule a one-shot flush for (lastWriteMs + cooldown). A
 * scheduled flush re-checks dirty and writes only if still needed.
 *
 * First-ever snapshot of an account bypasses the cooldown (so the user sees
 * the account appear in RSVault on first login rather than waiting 15 min).
 *
 * On logout: if flushOnLogout() is on and the account is dirty, flush now.
 */
package com.persistentbank;

import com.google.inject.Provides;
import com.google.gson.Gson;

import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Bank Wealth Dashboard",
	description = "Snapshots bank/inventory/equipment/GE/seed vault to disk for RSVault.",
	tags = {"bank", "inventory", "export", "rsvault", "snapshot"}
)
public class PersistentBankPlugin extends Plugin
{
	/** Equipment slot names in the order RuneLite exposes them on the
	 *  equipment container. Index matches
	 *  net.runelite.api.kit.KitType.ordinal(). */
	private static final String[] EQUIPMENT_SLOTS = {
		"HEAD", "CAPE", "AMULET", "WEAPON", "TORSO", "SHIELD",
		"ARMS", "LEGS", "HAIR", "HANDS", "BOOTS", "JAW",
		"RING", "AMMO"
	};

	/** Grace window after first-sight during which every event flushes
	 *  immediately, bypassing the cooldown. Lets the login burst land
	 *  (GE events fire before the player has spawned, inventory/equipment
	 *  arrive moments later, display name resolves last). 30s is enough
	 *  to cover a cold login without meaningfully loosening the rate
	 *  limiter. */
	private static final long FIRST_WRITE_GRACE_MS = 30_000L;

	/** Number of game ticks to keep retrying the initial-container sync
	 *  after a LOGGED_IN transition. A tick is ~0.6s, so 100 gives us
	 *  ~60 seconds to cover the window where the client is "in" but
	 *  either accountHash or the INVENTORY/EQUIPMENT containers haven't
	 *  been populated yet. Once both are captured we stop early. */
	private static final int INITIAL_SYNC_TICKS = 100;

	@Inject private Client client;
	@Inject private Gson gson;
	@Inject private PersistentBankConfig config;
	@Inject private ScheduledExecutorService executor;
	@Inject private ItemManager itemManager;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ClientThread clientThread;

	private SnapshotWriter writer;
	private SnapshotReader reader;
	private Path snapshotDir;

	/** Side panel. Created on startUp, reused across refresh cycles. */
	private WealthPanel panel;

	/** Toolbar icon that opens the wealth panel. Held onto so we can
	 *  unregister in shutDown. */
	private NavigationButton navButton;

	/** One mutable state block per Jagex account. Keyed by accountHash. */
	private final Map<Long, AccountState> accounts = new HashMap<>();

	/** Countdown of game ticks remaining for the post-login initial sync.
	 *  Set to INITIAL_SYNC_TICKS when LOGGED_IN fires; decremented on every
	 *  GameTick. Reset to 0 (i.e. stop retrying) once inventory & equipment
	 *  have both been captured. */
	private int initialSyncTicksRemaining;

	// ---- Guice binding -----------------------------------------------------

	@Provides
	PersistentBankConfig provideConfig(ConfigManager cm)
	{
		return cm.getConfig(PersistentBankConfig.class);
	}

	// ---- plugin lifecycle --------------------------------------------------

	@Override
	protected void startUp()
	{
		writer = new SnapshotWriter(gson);
		reader = new SnapshotReader();
		snapshotDir = resolveSnapshotDir();

		// Wealth panel. The panel itself is UI-only; the plugin owns the
		// disk-scan and open-folder callbacks because they want access to
		// snapshotDir / the executor thread.
		panel = new WealthPanel(this::refreshFromClient, this::openSnapshotFolder, snapshotDir);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		NavigationButton.NavigationButtonBuilder b = NavigationButton.builder()
			.tooltip("Persistent Bank")
			.priority(7)
			.panel(panel);
		if (icon != null)
		{
			b.icon(icon);
		}
		navButton = b.build();
		clientToolbar.addNavigation(navButton);

		// Kick off an initial disk-scan so the panel shows cached wealth
		// from previous sessions the moment the user opens it. Runs off the
		// EDT / client thread so it doesn't stall startup.
		executor.submit(this::refreshPanel);

		log.info("Persistent Bank started. Snapshot dir: {}", snapshotDir);
	}

	@Override
	protected void shutDown()
	{
		// Flush any pending dirty accounts on plugin disable.
		synchronized (accounts)
		{
			for (AccountState s : accounts.values())
			{
				cancelPending(s);
				if (s.dirty)
				{
					flush(s, "shutdown");
				}
			}
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
		log.info("Persistent Bank stopped.");
	}

	private Path resolveSnapshotDir()
	{
		String override = config.snapshotDirOverride();
		if (override != null && !override.trim().isEmpty())
		{
			return Paths.get(override.trim());
		}
		return RuneLite.RUNELITE_DIR.toPath().resolve("persistent-bank");
	}

	// ---- event handlers ----------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState gs = e.getGameState();
		if (gs == GameState.LOGIN_SCREEN || gs == GameState.HOPPING)
		{
			// Flush-on-logout, if enabled. We flush across all tracked
			// accounts because HOPPING can drop account context before the
			// next GameState event fires.
			if (!config.flushOnLogout())
			{
				return;
			}
			synchronized (accounts)
			{
				for (AccountState s : accounts.values())
				{
					cancelPending(s);
					if (s.dirty)
					{
						flush(s, "logout");
					}
				}
			}
		}
		else if (gs == GameState.LOGGED_IN)
		{
			// Belt-and-braces initial sync. Live ItemContainerChanged events
			// for INVENTORY / EQUIPMENT fire on container CHANGES, which
			// means RuneLite will not emit them on login if a container is
			// unchanged-empty (e.g. a fresh account with nothing worn and
			// an empty backpack). On top of that, the LOGGED_IN transition
			// can race ahead of both accountHash resolution and the
			// inventory/equipment packets, so a single-shot read here
			// sometimes returns null. We arm a short retry window
			// (INITIAL_SYNC_TICKS game ticks) and re-attempt on each tick
			// until both sections are captured, so empty-but-real
			// containers still land on disk.
			if (config.verboseLogging())
			{
				log.info("Persistent Bank: GameState -> LOGGED_IN, arming initial sync for {} ticks (accountHash={})",
					INITIAL_SYNC_TICKS, client.getAccountHash());
			}
			initialSyncTicksRemaining = INITIAL_SYNC_TICKS;
			syncInitialContainers();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		if (initialSyncTicksRemaining <= 0)
		{
			return;
		}
		initialSyncTicksRemaining--;
		syncInitialContainers();
	}

	private void syncInitialContainers()
	{
		AccountState s = stateForCurrentAccount();
		if (s == null)
		{
			if (config.verboseLogging() && initialSyncTicksRemaining == 0)
			{
				log.info("Persistent Bank: initial sync exhausted without resolving account (accountHash={})",
					client.getAccountHash());
			}
			return;
		}
		boolean changed = false;

		if (config.snapshotInventory() && s.inventory == null)
		{
			ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
			if (inv != null)
			{
				s.inventory = toContainerItems(inv);
				s.inventoryUpdatedAt = System.currentTimeMillis();
				changed = true;
				if (config.verboseLogging())
				{
					log.info("Persistent Bank: initial sync captured INVENTORY ({} items)",
						s.inventory.size());
				}
			}
		}
		if (config.snapshotEquipment() && s.equipment == null)
		{
			ItemContainer eq = client.getItemContainer(InventoryID.EQUIPMENT);
			if (eq != null)
			{
				s.equipment = toEquipmentItems(eq);
				s.equipmentUpdatedAt = System.currentTimeMillis();
				changed = true;
				if (config.verboseLogging())
				{
					log.info("Persistent Bank: initial sync captured EQUIPMENT ({} items)",
						s.equipment.size());
				}
			}
		}
		if (config.snapshotGrandExchange() && s.grandExchange == null)
		{
			// The GE offer array is available the moment we're logged in, even
			// when every slot is empty — capture it up front so a write can't
			// record a total missing GE-held wealth (can be a big slice).
			if (client.getGrandExchangeOffers() != null)
			{
				s.grandExchange = readAllGeSlots();
				s.geUpdatedAt = System.currentTimeMillis();
				changed = true;
			}
		}

		// Bank and seed vault only populate when the player actually opens
		// them, so we intentionally don't poll for those here — there's
		// nothing to read yet.

		if (changed)
		{
			s.touch();
			maybeFlush(s);
		}

		// Early-stop: once both sections are populated there's nothing
		// more for onGameTick to do, so kill the retry window.
		if ((!config.snapshotInventory() || s.inventory != null)
			&& (!config.snapshotEquipment() || s.equipment != null)
			&& (!config.snapshotGrandExchange() || s.grandExchange != null))
		{
			initialSyncTicksRemaining = 0;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		int id = e.getContainerId();
		ItemContainer c = e.getItemContainer();
		if (config.verboseLogging())
		{
			log.info("Persistent Bank: ItemContainerChanged id={} size={}",
				id, c == null || c.getItems() == null ? -1 : c.getItems().length);
		}

		if (id == InventoryID.BANK.getId())
		{
			if (!config.snapshotBank()) return;
			AccountState s = stateForCurrentAccount();
			if (s == null) return;
			List<AccountState.ContainerItem> incoming = toContainerItems(c);
			if (isEmptyRead(incoming))
			{
				if (config.verboseLogging())
				{
					log.info("Persistent Bank: ignoring empty BANK event (keeping {} held items)", s.bank.size());
				}
				return;
			}
			s.bank = incoming;
			s.bankUpdatedAt = System.currentTimeMillis();
			s.touch();
			maybeFlush(s);
		}
		else if (id == InventoryID.INVENTORY.getId())
		{
			if (!config.snapshotInventory()) return;
			AccountState s = stateForCurrentAccount();
			if (s == null) return;
			s.inventory = toContainerItems(c);
			s.inventoryUpdatedAt = System.currentTimeMillis();
			s.touch();
			maybeFlush(s);
		}
		else if (id == InventoryID.EQUIPMENT.getId())
		{
			if (!config.snapshotEquipment()) return;
			AccountState s = stateForCurrentAccount();
			if (s == null) return;
			s.equipment = toEquipmentItems(c);
			s.equipmentUpdatedAt = System.currentTimeMillis();
			s.touch();
			maybeFlush(s);
		}
		else if (id == InventoryID.SEED_VAULT.getId())
		{
			if (!config.snapshotSeedVault()) return;
			AccountState s = stateForCurrentAccount();
			if (s == null) return;
			List<AccountState.ContainerItem> incoming = toContainerItems(c);
			if (isEmptyRead(incoming))
			{
				return;
			}
			s.seedVault = incoming;
			s.seedVaultUpdatedAt = System.currentTimeMillis();
			s.touch();
			maybeFlush(s);
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
	{
		if (!config.snapshotGrandExchange()) return;
		AccountState s = stateForCurrentAccount();
		if (s == null) return;
		// Rebuild the full 8-slot view on every GE change. Cheaper than
		// tracking deltas and keeps the JSON authoritative.
		s.grandExchange = readAllGeSlots();
		s.geUpdatedAt = System.currentTimeMillis();
		s.touch();
		maybeFlush(s);
	}

	// ---- state lookup ------------------------------------------------------

	/** Returns the AccountState for the currently-logged-in account,
	 *  creating one on first sight. Returns null if no account is
	 *  logged in.
	 *
	 *  RuneLite's Client.getAccountHash() returns -1L as the documented
	 *  sentinel for "no account logged in". Real Jagex account hashes
	 *  are 64-bit values that can appear negative when read as signed
	 *  Java longs (high bit set), so we must check the exact -1L
	 *  sentinel rather than "hash <= 0" — otherwise we silently drop
	 *  every account whose hash happens to land in the negative half
	 *  of the signed-long range. */
	private AccountState stateForCurrentAccount()
	{
		long hash = client.getAccountHash();
		if (hash == -1L)
		{
			return null;
		}
		AccountState s;
		synchronized (accounts)
		{
			s = accounts.computeIfAbsent(hash, h ->
			{
				AccountState ns = new AccountState(h);
				// Seed last-known bank / seed-vault / GE from disk so a flush
				// fired before the player re-opens those interfaces this session
				// can't overwrite the saved snapshot with empty sections.
				reader.hydrate(snapshotDir, ns);
				return ns;
			});
		}
		// Refresh display name every time — it's cheap and cheap to keep
		// current across name changes.
		if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
		{
			s.displayName = client.getLocalPlayer().getName();
		}
		return s;
	}

	// ---- container -> plain data ------------------------------------------

	private List<AccountState.ContainerItem> toContainerItems(ItemContainer c)
	{
		List<AccountState.ContainerItem> out = new ArrayList<>();
		if (c == null) return out;
		Item[] items = c.getItems();
		if (items == null) return out;
		for (Item it : items)
		{
			int id = it.getId();
			int qty = it.getQuantity();
			if (id <= 0 || qty <= 0)
			{
				continue; // empty slot
			}
			if (isPlaceholder(id))
			{
				// Bank placeholder slot — the game shows "0" on it and
				// it represents an item that *used* to be here. Skipping
				// these matches what the player actually owns.
				continue;
			}
			// RuneLite exposes noted items as a different itemId than the
			// unnoted form. We keep the raw id and set noted=false; the
			// reader can look up "is this a noted variant?" against its
			// own item mapping if needed.
			out.add(new AccountState.ContainerItem(id, qty, false));
		}
		return out;
	}

	/**
	 * True if the given itemId is a bank-placeholder variant. Placeholders
	 * have a non-(-1) {@code placeholderTemplateId} on their
	 * {@link ItemComposition}; real items return -1. This is the canonical
	 * RuneLite check for the "slot shows 0, kept as a shortcut for later"
	 * state. Wrapped in a try/catch so a transient lookup failure during
	 * the login burst never blows up the snapshot path.
	 */
	private boolean isPlaceholder(int itemId)
	{
		try
		{
			ItemComposition comp = itemManager.getItemComposition(itemId);
			return comp != null && comp.getPlaceholderTemplateId() != -1;
		}
		catch (Exception e)
		{
			return false;
		}
	}

	private List<AccountState.EquipmentItem> toEquipmentItems(ItemContainer c)
	{
		List<AccountState.EquipmentItem> out = new ArrayList<>();
		if (c == null) return out;
		Item[] items = c.getItems();
		if (items == null) return out;
		for (int i = 0; i < items.length; i++)
		{
			Item it = items[i];
			if (it == null) continue;
			int id = it.getId();
			int qty = it.getQuantity();
			if (id <= 0 || qty <= 0) continue;
			String slot = (i < EQUIPMENT_SLOTS.length) ? EQUIPMENT_SLOTS[i] : String.valueOf(i);
			out.add(new AccountState.EquipmentItem(id, qty, slot));
		}
		return out;
	}

	private List<AccountState.GeSlot> readAllGeSlots()
	{
		List<AccountState.GeSlot> out = new ArrayList<>();
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return out;
		}
		for (int i = 0; i < offers.length; i++)
		{
			GrandExchangeOffer o = offers[i];
			if (o == null || o.getState() == GrandExchangeOfferState.EMPTY)
			{
				out.add(AccountState.GeSlot.empty(i));
				continue;
			}
			int itemId = o.getItemId();
			int totalQty = o.getTotalQuantity();
			int tradedQty = o.getQuantitySold();
			int pricePer = o.getPrice();
			int spent = o.getSpent();
			String state = o.getState() == null ? "UNKNOWN" : o.getState().name();
			// itemId of 0 can slip through as a transient state; treat as empty.
			if (itemId <= 0)
			{
				out.add(AccountState.GeSlot.empty(i));
				continue;
			}
			out.add(new AccountState.GeSlot(
				i, state, itemId, totalQty, tradedQty, pricePer, spent
			));
		}
		return out;
	}

	// ---- rate limiter ------------------------------------------------------

	/**
	 * Decide whether to flush now or defer. Called after any container event.
	 * Must be invoked from the client thread (RuneLite event dispatch).
	 */
	private void maybeFlush(AccountState s)
	{
		long now = System.currentTimeMillis();
		long cooldownMs = Math.max(1, config.minMinutesBetweenWrites()) * 60_000L;

		// First-ever snapshot for this account: write immediately and open
		// the grace window. Stamp firstSeenAtMs BEFORE flush() so follow-up
		// events on the same login burst recognize we're still in the window.
		if (!s.hasWrittenOnce && config.firstSnapshotImmediate())
		{
			cancelPending(s);
			s.firstSeenAtMs = now;
			flush(s, "first-sight");
			return;
		}

		// Grace window: during the first N seconds after first-sight, every
		// event flushes immediately. This catches the login-burst sequence
		// where GE fires first (before player spawn), then inventory /
		// equipment / seed vault arrive, and finally the display name
		// becomes readable. Without this, those later events get parked
		// behind the 15-minute cooldown and the first file on disk is
		// missing bank/inventory/equipment plus the display name.
		if (s.hasWrittenOnce
			&& s.firstSeenAtMs > 0
			&& (now - s.firstSeenAtMs) < FIRST_WRITE_GRACE_MS)
		{
			cancelPending(s);
			flush(s, "first-burst");
			return;
		}

		long elapsed = now - s.lastWriteMs;
		if (elapsed >= cooldownMs)
		{
			cancelPending(s);
			flush(s, "cooldown-elapsed");
			return;
		}

		// Too soon. Make sure a deferred flush is queued so changes don't
		// get lost if nothing else fires for a while.
		if (s.pendingFlush == null || s.pendingFlush.isDone())
		{
			long delay = cooldownMs - elapsed;
			final AccountState captured = s;
			s.pendingFlush = executor.schedule(
				() -> deferredFlush(captured),
				delay,
				TimeUnit.MILLISECONDS);
			if (config.verboseLogging())
			{
				log.info("Persistent Bank: deferring flush for acct {} by {}ms", s.accountHash, delay);
			}
		}
	}

	private void deferredFlush(AccountState s)
	{
		// Re-check dirty: a successful flush between the scheduling and now
		// would have cleared it.
		if (s.dirty)
		{
			flush(s, "deferred");
		}
	}

	private void cancelPending(AccountState s)
	{
		if (s.pendingFlush != null)
		{
			s.pendingFlush.cancel(false);
			s.pendingFlush = null;
		}
	}

	private void flush(AccountState s, String reason)
	{
		if (!client.isClientThread())
		{
			// ItemManager price/composition lookups only return correct values on the client
			// thread; off-thread (deferred / shutdown flushes) every price comes back 0, which
			// zeroes out the whole snapshot. Run the valuation + write on the client thread.
			clientThread.invokeLater(() -> flush(s, reason));
			return;
		}
		try
		{
			long now = System.currentTimeMillis();

			// Recompute wealth totals using current GE prices. Cheap
			// (hashmap lookups inside ItemManager) and only runs at write
			// time, which is already rate-limited to once per 15 minutes
			// per account — so even on weak PCs the cost is negligible.
			// Done here (not in SnapshotWriter) so the writer stays a pure
			// serializer and doesn't pull an ItemManager dependency.
			recomputeValues(s);

			// A snapshot is complete only when every enabled wealth section has been observed
			// (or hydrated). An incomplete snapshot (e.g. bank never opened this session) holds
			// a partial total that must not be shown as net worth, so we flag it; the panel then
			// excludes it from the headline and the chart.
			boolean haveLive = (!config.snapshotInventory() || s.inventory != null)
				&& (!config.snapshotEquipment() || s.equipment != null)
				&& (!config.snapshotBank() || (s.bank != null && !s.bank.isEmpty()))
				&& (!config.snapshotGrandExchange() || s.grandExchange != null);
			s.complete = haveLive;

			writer.write(snapshotDir, s, now);
			// Append a wealth-history point (throttled to coalesce the login burst).
			// Only log a chart point once we have a complete picture: a positive
			// total plus the always-live sections (inventory, equipment) actually
			// captured, so a write fired in the first moments of login can't record
			// a partial number. (The snapshot file itself still writes regardless.)
			if (s.totalValueGp > 0L && haveLive
				&& (now - s.lastHistoryMs >= 60_000L || s.lastHistoryMs == 0L))
			{
				long v = s.totalValueGp;
				boolean collapse = s.lastHistoryValue > 0L && v * 2L < s.lastHistoryValue;
				boolean confirmsDrop = s.pendingLowValue > 0L
					&& v >= s.pendingLowValue - s.pendingLowValue / 6L
					&& v <= s.pendingLowValue + s.pendingLowValue / 6L;
				if (collapse && !confirmsDrop)
				{
					// A >50% single-step drop is almost always a capture glitch (real player
					// actions conserve wealth). Hold it until a second reading corroborates it,
					// so one bad read cannot crater the chart; a genuine drop still records next.
					s.pendingLowValue = v;
				}
				else
				{
					WealthHistory.append(snapshotDir, s.accountHash, now, v);
					s.lastHistoryMs = now;
					s.lastHistoryValue = v;
					s.pendingLowValue = 0L;
				}
			}
			s.lastWriteMs = now;
			s.dirty = false;
			s.hasWrittenOnce = true;
			if (config.verboseLogging())
			{
				log.info("Persistent Bank: wrote acct {} ({}) totalValueGp={}",
					s.accountHash, reason, s.totalValueGp);
			}

			// Let the wealth panel re-read the folder. Runs off the EDT
			// (SnapshotReader is safe on any thread; WealthPanel.update()
			// bounces the actual UI mutation to the EDT internally).
			if (panel != null)
			{
				executor.submit(this::refreshPanel);
			}
		}
		catch (Exception e)
		{
			log.warn("Persistent Bank: failed to write snapshot for {} ({}): {}",
				s.accountHash, reason, e.getMessage());
		}
	}

	// ---- wealth computation ------------------------------------------------

	/**
	 * Fill in the *ValueGp fields on {@code s} using current GE prices. Any
	 * price-lookup failure for a single item is swallowed — a missing price
	 * just contributes zero to the total, which is the right behaviour for
	 * items that aren't tradeable or aren't in the price cache yet.
	 */
	private long geValue(List<AccountState.GeSlot> slots)
	{
		if (slots == null || slots.isEmpty()) return 0L;
		long total = 0L;
		for (AccountState.GeSlot g : slots)
		{
			if (g == null || g.state == null) continue;
			String st = g.state;
			int itemId   = g.itemId    == null ? 0 : g.itemId;
			int totalQty = g.qtySought == null ? 0 : g.qtySought;
			int traded   = g.qtyTraded == null ? 0 : g.qtyTraded;
			int pricePer = g.pricePer  == null ? 0 : g.pricePer;
			int spent    = g.spent     == null ? 0 : g.spent;
			long unit = itemId > 0 ? priceFor(itemId) : 0L;

			boolean buy  = st.equals("BUYING")  || st.equals("BOUGHT") || st.equals("CANCELLED_BUY");
			boolean sell = st.equals("SELLING") || st.equals("SOLD")   || st.equals("CANCELLED_SELL");

			if (buy)
			{
				// Coins still committed to the offer (refunded on completion/cancel)
				// plus items already bought sitting in the collection box.
				long committed = (long) pricePer * totalQty - spent;
				if (committed < 0) committed = 0;
				total += committed + unit * (long) traded;
			}
			else if (sell)
			{
				// Items still up for sale plus coins already received, both of
				// which sit on the GE until the player collects.
				total += unit * (long) Math.max(0, totalQty - traded) + spent;
			}
			// EMPTY / UNKNOWN contribute nothing.
		}
		return total;
	}
	/**
	 * True when a fresh read of an open-on-demand section (bank / seed vault) is
	 * empty/null while we already hold a populated snapshot. An empty bank event is
	 * almost always the interface closing or the container being momentarily reused,
	 * not the player emptying their bank, so accepting it would zero out a huge slice
	 * of wealth for that write. We keep the last-known contents instead.
	 */
	private static boolean isEmptyRead(List<AccountState.ContainerItem> incoming)
	{
		// An empty read of an open-on-demand section (bank / seed vault) is never trusted:
		// the bank reports empty when its interface closes, is reused, or has not finished
		// loading, and a genuinely empty bank holds no wealth anyway. Only a non-empty
		// observation may set or replace the section, so a stray empty event can neither
		// zero out a known bank nor fabricate a 'complete' account still missing its bank.
		return incoming == null || incoming.isEmpty();
	}

	/**
	 * Value a populated open-on-demand section, but never report zero for a section
	 * that still holds items: a non-empty list that prices to 0 means the GE price
	 * cache was not warm yet (common during the login burst), so we keep the last
	 * known-good value rather than let a cold read zero out a slice of wealth.
	 */
	private long sectionValueOrKeep(List<AccountState.ContainerItem> items, long previous)
	{
		long v = containerValue(items);
		if (v == 0L && previous > 0L && items != null && !items.isEmpty())
		{
			return previous;
		}
		return v;
	}

	private void recomputeValues(AccountState s)
	{
		s.bankValueGp = sectionValueOrKeep(s.bank, s.bankValueGp);
		s.inventoryValueGp = containerValue(s.inventory);
		s.equipmentValueGp = equipmentValue(s.equipment);
		s.seedVaultValueGp = sectionValueOrKeep(s.seedVault, s.seedVaultValueGp);
		s.geValueGp        = geValue(s.grandExchange);
		s.totalValueGp =
			s.bankValueGp + s.inventoryValueGp
			+ s.equipmentValueGp + s.seedVaultValueGp
			+ s.geValueGp;
	}

	private long containerValue(List<AccountState.ContainerItem> items)
	{
		if (items == null || items.isEmpty()) return 0L;
		long total = 0L;
		for (AccountState.ContainerItem it : items)
		{
			total += priceFor(it.id) * (long) it.qty;
		}
		return total;
	}

	private long equipmentValue(List<AccountState.EquipmentItem> items)
	{
		if (items == null || items.isEmpty()) return 0L;
		long total = 0L;
		for (AccountState.EquipmentItem it : items)
		{
			total += priceFor(it.id) * (long) it.qty;
		}
		return total;
	}

	/** Safe GE-price lookup. Returns 0 for untradeables or any price the
	 *  ItemManager can't resolve right now — we'd rather undercount than
	 *  crash the write path. */
	private long priceFor(int itemId)
	{
		if (itemId <= 0) return 0L;
		try
		{
			int p = itemManager.getItemPrice(itemId);
			return Math.max(0, p);
		}
		catch (Exception e)
		{
			return 0L;
		}
	}

	// ---- panel callbacks ---------------------------------------------------

	/** Re-read the snapshot folder and push the results into the panel.
	 *  Called both on the Refresh button and after every successful write.
	 *  Safe to call from any thread; if invoked on the EDT we hop to the
	 *  executor so disk I/O never blocks the UI. */
	private void refreshPanel()
	{
		if (panel == null) return;
		Runnable job = () ->
		{
			if (reader == null || snapshotDir == null || panel == null) return;
			List<SnapshotReader.AccountSummary> summaries = reader.readAll(snapshotDir);
			if (panel != null)
			{
				panel.update(summaries);
			}
		};
		if (javax.swing.SwingUtilities.isEventDispatchThread())
		{
			executor.submit(job);
		}
		else
		{
			job.run();
		}
	}

	/** Open the snapshot folder in the OS file browser. Delegated from the
	 *  Folder button in the wealth panel. */
	/** Force-capture the live account and write it immediately, bypassing the
	 *  rate-limit cooldown. Wired to the panel's Refresh button: re-reads every
	 *  container the client currently holds, re-prices, and flushes now instead
	 *  of waiting for the next scheduled write. */
	private void refreshFromClient()
	{
		clientThread.invokeLater(() ->
		{
			if (!captureLiveAccount())
			{
				// Not logged in / nothing to capture — still re-read disk.
				executor.submit(this::refreshPanel);
			}
			// On a successful capture, flush() already triggers refreshPanel.
		});
	}

	/** Re-read every container the client currently holds for the logged-in
	 *  account, then flush. Bank / seed vault are only available if the player
	 *  has opened them this session; a missing section keeps its last-known
	 *  (hydrated) value rather than being cleared. Must run on the client
	 *  thread. Returns false when no account is logged in. */
	private boolean captureLiveAccount()
	{
		AccountState s = stateForCurrentAccount();
		if (s == null)
		{
			return false;
		}
		long now = System.currentTimeMillis();
		if (config.snapshotInventory())
		{
			ItemContainer c = client.getItemContainer(InventoryID.INVENTORY);
			if (c != null)
			{
				s.inventory = toContainerItems(c);
				s.inventoryUpdatedAt = now;
			}
		}
		if (config.snapshotEquipment())
		{
			ItemContainer c = client.getItemContainer(InventoryID.EQUIPMENT);
			if (c != null)
			{
				s.equipment = toEquipmentItems(c);
				s.equipmentUpdatedAt = now;
			}
		}
		if (config.snapshotBank())
		{
			ItemContainer c = client.getItemContainer(InventoryID.BANK);
			if (c != null)
			{
				List<AccountState.ContainerItem> incoming = toContainerItems(c);
				if (!isEmptyRead(incoming))
				{
					s.bank = incoming;
					s.bankUpdatedAt = now;
				}
			}
		}
		if (config.snapshotSeedVault())
		{
			ItemContainer c = client.getItemContainer(InventoryID.SEED_VAULT);
			if (c != null)
			{
				List<AccountState.ContainerItem> incoming = toContainerItems(c);
				if (!isEmptyRead(incoming))
				{
					s.seedVault = incoming;
					s.seedVaultUpdatedAt = now;
				}
			}
		}
		if (config.snapshotGrandExchange() && client.getGrandExchangeOffers() != null)
		{
			s.grandExchange = readAllGeSlots();
			s.geUpdatedAt = now;
		}
		s.touch();
		cancelPending(s);
		flush(s, "manual-refresh");
		return true;
	}

	private void openSnapshotFolder()
	{
		try
		{
			java.nio.file.Files.createDirectories(snapshotDir);
		}
		catch (Exception ignored)
		{
			// If we can't create it we can't open it — WealthPanel will
			// just silently no-op below.
		}
		WealthPanel.openInFileBrowser(snapshotDir);
	}
}

/*
 * Persistent Bank — RuneLite plugin
 *
 * Reads the snapshot folder on disk and returns lightweight per-account
 * summaries for the Wealth panel. We intentionally do NOT reparse item lists
 * or recompute prices here — the values embedded by SnapshotWriter at
 * write-time are the source of truth. That keeps the panel's refresh path
 * trivial (read a few small JSON files, no price lookups, no item iteration)
 * so it stays cheap even on weak PCs with many accounts.
 */
package com.persistentbank;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

class SnapshotReader
{
	/** Lightweight view of one account's on-disk snapshot, suitable for
	 *  rendering in the Wealth panel. Full item data stays on disk. */
	static class AccountSummary
	{
		long accountHash;
		String displayName;
		long lastUpdated;
		long totalValueGp;
		long bankValueGp;
		long inventoryValueGp;
		long equipmentValueGp;
		long seedVaultValueGp;
		long geValueGp;
		boolean complete;
	}

	/** Scan {@code snapshotDir} for *.json files and parse each into an
	 *  AccountSummary. Swallows per-file parse errors so one corrupted
	 *  snapshot doesn't hide the rest. Never throws; returns an empty list
	 *  if the directory is missing or unreadable. Safe to call from a
	 *  background thread — does not touch any RuneLite client state. */
	List<AccountSummary> readAll(Path snapshotDir)
	{
		List<AccountSummary> out = new ArrayList<>();
		if (snapshotDir == null || !Files.isDirectory(snapshotDir))
		{
			return out;
		}
		try (DirectoryStream<Path> stream = Files.newDirectoryStream(snapshotDir, "*.json"))
		{
			for (Path p : stream)
			{
				try
				{
					AccountSummary s = readOne(p);
					if (s != null)
					{
						out.add(s);
					}
				}
				catch (Exception ignored)
				{
					// Corrupt / partial / foreign file — skip silently.
				}
			}
		}
		catch (IOException ignored)
		{
			// Directory-level failure; return whatever we got (likely empty).
		}
		return out;
	}

	private AccountSummary readOne(Path p) throws IOException
	{
		String raw = Files.readString(p);
		// Use the instance-style JsonParser API (pre-2.8.6 Gson) since
		// RuneLite bundles an older Gson than the one that added the
		// static JsonParser.parseString(). Both APIs return a JsonElement;
		// the instance form is just slightly more ceremony.
		@SuppressWarnings("deprecation")
		JsonElement parsed = new JsonParser().parse(raw);
		if (!parsed.isJsonObject())
		{
			return null;
		}
		JsonObject root = parsed.getAsJsonObject();

		AccountSummary s = new AccountSummary();
		s.accountHash = asLong(root, "accountHash");
		s.displayName = asString(root, "displayName", "");
		s.lastUpdated = asLong(root, "lastUpdated");
		s.totalValueGp = asLong(root, "totalValueGp");
		s.bankValueGp = sectionValue(root, "bank");
		s.inventoryValueGp = sectionValue(root, "inventory");
		s.equipmentValueGp = sectionValue(root, "equipment");
		s.seedVaultValueGp = sectionValue(root, "seedVault");
		s.geValueGp = sectionValue(root, "grandExchange");
		s.complete = !root.has("complete") || asBool(root, "complete");

		// Fallback: older snapshots pre-dating the wealth-panel work don't
		// have a top-level totalValueGp. Derive from sections so those
		// accounts still show a sensible grand total without waiting for
		// the user to log in again.
		if (s.totalValueGp <= 0)
		{
			s.totalValueGp =
				s.bankValueGp + s.inventoryValueGp
				+ s.equipmentValueGp + s.seedVaultValueGp
				+ s.geValueGp;
		}

		if (s.accountHash == -1L)
		{
			// Sentinel for "no account logged in" — not a real snapshot.
			// Anything else (including negative-signed Jagex hashes, which
			// are valid 64-bit identifiers whose high bit happens to be set)
			// must be accepted, otherwise the panel silently drops roughly
			// half of all accounts.
			return null;
		}
		return s;
	}

	private static long sectionValue(JsonObject root, String section)
	{
		if (!root.has(section) || !root.get(section).isJsonObject())
		{
			return 0L;
		}
		return asLong(root.getAsJsonObject(section), "totalValueGp");
	}

	private static long asLong(JsonObject o, String key)
	{
		if (o == null || !o.has(key))
		{
			return 0L;
		}
		try
		{
			return o.get(key).getAsLong();
		}
		catch (Exception e)
		{
			return 0L;
		}
	}

	private static boolean asBool(JsonObject o, String key)
	{
		if (o == null || !o.has(key))
		{
			return true;
		}
		try
		{
			return o.get(key).getAsBoolean();
		}
		catch (Exception e)
		{
			return true;
		}
	}

	private static String asString(JsonObject o, String key, String fallback)
	{
		if (o == null || !o.has(key))
		{
			return fallback;
		}
		try
		{
			return o.get(key).getAsString();
		}
		catch (Exception e)
		{
			return fallback;
		}
	}

	/** Seed an in-memory {@link AccountState} from this account's last
	 *  on-disk snapshot. Only the "open-on-demand" sections (bank, seed
	 *  vault, Grand Exchange) are restored: those don't get re-read every
	 *  login, so without this a flush fired before the player re-opens them
	 *  would overwrite the saved file with empty sections. Inventory and
	 *  equipment are deliberately left alone — the plugin re-reads those live
	 *  on every login. No-op when there is no prior file or it can't be
	 *  parsed. Safe on any thread; touches no client state. */
	void hydrate(Path snapshotDir, AccountState s)
	{
		if (snapshotDir == null || s == null)
		{
			return;
		}
		Path p = snapshotDir.resolve(s.accountHash + ".json");
		if (!Files.isRegularFile(p))
		{
			return;
		}
		try
		{
			String raw = Files.readString(p);
			@SuppressWarnings("deprecation")
			JsonElement parsed = new JsonParser().parse(raw);
			if (!parsed.isJsonObject())
			{
				return;
			}
			JsonObject root = parsed.getAsJsonObject();

			String dn = asString(root, "displayName", "");
			if (!dn.isEmpty())
			{
				s.displayName = dn;
			}

			JsonObject bank = sectionObj(root, "bank");
			if (bank != null)
			{
				List<AccountState.ContainerItem> items = parseContainerItems(bank);
				if (items != null && !items.isEmpty())
				{
					s.bank = items;
					s.bankUpdatedAt = asLong(bank, "updatedAt");
					s.bankValueGp = asLong(bank, "totalValueGp");
				}
			}

			JsonObject sv = sectionObj(root, "seedVault");
			if (sv != null)
			{
				List<AccountState.ContainerItem> items = parseContainerItems(sv);
				if (items != null && !items.isEmpty())
				{
					s.seedVault = items;
					s.seedVaultUpdatedAt = asLong(sv, "updatedAt");
					s.seedVaultValueGp = asLong(sv, "totalValueGp");
				}
			}

			JsonObject ge = sectionObj(root, "grandExchange");
			if (ge != null)
			{
				List<AccountState.GeSlot> slots = parseGeSlots(ge);
				if (slots != null)
				{
					s.grandExchange = slots;
					s.geUpdatedAt = asLong(ge, "updatedAt");
					s.geValueGp = asLong(ge, "totalValueGp");
				}
			}
		}
		catch (Exception ignored)
		{
			// Corrupt / partial snapshot — start clean rather than fail.
		}
	}

	private static JsonObject sectionObj(JsonObject root, String name)
	{
		if (root == null || !root.has(name) || !root.get(name).isJsonObject())
		{
			return null;
		}
		return root.getAsJsonObject(name);
	}

	private static List<AccountState.ContainerItem> parseContainerItems(JsonObject section)
	{
		if (!section.has("items") || !section.get("items").isJsonArray())
		{
			return null;
		}
		List<AccountState.ContainerItem> out = new ArrayList<>();
		for (JsonElement el : section.getAsJsonArray("items"))
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject o = el.getAsJsonObject();
			int id = (int) asLong(o, "id");
			int qty = (int) asLong(o, "qty");
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			boolean noted = o.has("noted") && !o.get("noted").isJsonNull() && o.get("noted").getAsBoolean();
			out.add(new AccountState.ContainerItem(id, qty, noted));
		}
		return out;
	}

	private static List<AccountState.GeSlot> parseGeSlots(JsonObject section)
	{
		if (!section.has("slots") || !section.get("slots").isJsonArray())
		{
			return null;
		}
		List<AccountState.GeSlot> out = new ArrayList<>();
		for (JsonElement el : section.getAsJsonArray("slots"))
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject o = el.getAsJsonObject();
			int slot = (int) asLong(o, "slot");
			String state = asString(o, "state", "EMPTY");
			out.add(new AccountState.GeSlot(
				slot, state,
				asIntOrNull(o, "itemId"),
				asIntOrNull(o, "qtySought"),
				asIntOrNull(o, "qtyTraded"),
				asIntOrNull(o, "pricePer"),
				asIntOrNull(o, "spent")));
		}
		return out;
	}

	private static Integer asIntOrNull(JsonObject o, String key)
	{
		if (o == null || !o.has(key) || o.get(key).isJsonNull())
		{
			return null;
		}
		try
		{
			return o.get(key).getAsInt();
		}
		catch (Exception e)
		{
			return null;
		}
	}
}

/*
 * Persistent Bank — RuneLite plugin
 *
 * Serializes an AccountState to a stable JSON shape and writes it atomically
 * to <snapshotDir>/<accountHash>.json. The JSON schema is the contract with
 * RSVault; see README.md § "Snapshot schema" before changing anything.
 *
 * Atomic write pattern: write to "<hash>.json.tmp", fsync, then Files.move
 * with ATOMIC_MOVE + REPLACE_EXISTING. This guarantees RSVault's file watcher
 * never sees a half-written file.
 */
package com.persistentbank;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;

class SnapshotWriter
{
	private final Gson gson;

	SnapshotWriter(Gson gson)
	{
		this.gson = gson;
	}

	/** Build the on-disk JSON object for one account. Never mutates
	 *  {@code state}. */
	JsonObject build(AccountState state, long nowMs)
	{
		JsonObject root = new JsonObject();
		root.addProperty("schemaVersion", 1);
		root.addProperty("accountHash", state.accountHash);
		root.addProperty("displayName", state.displayName == null ? "" : state.displayName);
		root.addProperty("lastUpdated", nowMs);
		// Top-level totalValueGp: sum of bank + inventory + equipment + seed
		// vault + Grand Exchange, valued at write time. The GE figure counts
		// coins still committed to open offers plus items and coins waiting in
		// the collection box, which have already left the other containers, so
		// it is added without double-counting.
		root.addProperty("totalValueGp", state.totalValueGp);
		root.addProperty("complete", state.complete);

		if (state.bank != null)
		{
			root.add("bank", containerSection(state.bank, state.bankUpdatedAt, state.bankValueGp));
		}
		if (state.inventory != null)
		{
			root.add("inventory", containerSection(state.inventory, state.inventoryUpdatedAt, state.inventoryValueGp));
		}
		if (state.equipment != null)
		{
			root.add("equipment", equipmentSection(state.equipment, state.equipmentUpdatedAt, state.equipmentValueGp));
		}
		if (state.seedVault != null)
		{
			root.add("seedVault", containerSection(state.seedVault, state.seedVaultUpdatedAt, state.seedVaultValueGp));
		}
		if (state.grandExchange != null)
		{
			root.add("grandExchange", geSection(state.grandExchange, state.geUpdatedAt, state.geValueGp));
		}

		return root;
	}

	/** Serialize {@code state} to JSON and atomically replace the account's
	 *  file in {@code snapshotDir}. */
	void write(Path snapshotDir, AccountState state, long nowMs) throws IOException
	{
		Files.createDirectories(snapshotDir);

		JsonObject root = build(state, nowMs);
		String json = gson.toJson(root);

		Path target = snapshotDir.resolve(state.accountHash + ".json");
		Path tmp = snapshotDir.resolve(state.accountHash + ".json.tmp");

		Files.writeString(tmp, json);
		try
		{
			Files.move(tmp, target,
				StandardCopyOption.ATOMIC_MOVE,
				StandardCopyOption.REPLACE_EXISTING);
		}
		catch (Exception atomicFailed)
		{
			// Some filesystems (exotic network mounts) don't support atomic
			// move. Fall back to a plain replace.
			Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	// ---- section builders --------------------------------------------------

	private JsonObject containerSection(List<AccountState.ContainerItem> items, long updatedAt, long valueGp)
	{
		JsonObject s = new JsonObject();
		s.addProperty("updatedAt", updatedAt);
		s.addProperty("totalValueGp", valueGp);
		JsonArray arr = new JsonArray();
		for (AccountState.ContainerItem it : items)
		{
			JsonObject o = new JsonObject();
			o.addProperty("id", it.id);
			o.addProperty("qty", it.qty);
			if (it.noted)
			{
				o.addProperty("noted", true);
			}
			arr.add(o);
		}
		s.add("items", arr);
		return s;
	}

	private JsonObject equipmentSection(List<AccountState.EquipmentItem> items, long updatedAt, long valueGp)
	{
		JsonObject s = new JsonObject();
		s.addProperty("updatedAt", updatedAt);
		s.addProperty("totalValueGp", valueGp);
		JsonArray arr = new JsonArray();
		for (AccountState.EquipmentItem it : items)
		{
			JsonObject o = new JsonObject();
			o.addProperty("id", it.id);
			o.addProperty("qty", it.qty);
			o.addProperty("slot", it.slot);
			arr.add(o);
		}
		s.add("items", arr);
		return s;
	}

	private JsonObject geSection(List<AccountState.GeSlot> slots, long updatedAt, long valueGp)
	{
		JsonObject s = new JsonObject();
		s.addProperty("updatedAt", updatedAt);
		s.addProperty("totalValueGp", valueGp);
		JsonArray arr = new JsonArray();
		for (AccountState.GeSlot slot : slots)
		{
			JsonObject o = new JsonObject();
			o.addProperty("slot", slot.slot);
			o.addProperty("state", slot.state);
			if (slot.itemId != null) o.addProperty("itemId", slot.itemId);
			if (slot.qtySought != null) o.addProperty("qtySought", slot.qtySought);
			if (slot.qtyTraded != null) o.addProperty("qtyTraded", slot.qtyTraded);
			if (slot.pricePer != null) o.addProperty("pricePer", slot.pricePer);
			if (slot.spent != null) o.addProperty("spent", slot.spent);
			arr.add(o);
		}
		s.add("slots", arr);
		return s;
	}
}

/*
 * Persistent Bank — RuneLite plugin
 *
 * A compact wealth-over-time chart drawn in the style of a TradingView "mini"
 * preview: a single smoothed area line, a gradient fill fading into the
 * background, minimal time labels along the bottom, and a hover crosshair that
 * reads out the value and date under the cursor. The line is green when the
 * value rose across the visible window and red when it fell.
 *
 * The component is purely a renderer: it is handed a prepared, summed,
 * downsampled series plus the window bounds and draws it. All series assembly
 * lives in WealthHistory; all selection/period logic lives in WealthPanel.
 */
package com.persistentbank;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.GeneralPath;
import java.text.SimpleDateFormat;
import java.util.Collections;
import java.util.Date;
import java.util.List;
import java.util.TimeZone;

import javax.swing.JPanel;

import net.runelite.client.ui.FontManager;

class WealthChart extends JPanel
{
	private static final Color UP = new Color(0x26, 0xA6, 0x9A);   // TradingView teal-green
	private static final Color DOWN = new Color(0xEF, 0x53, 0x50); // red
	private static final Color MUTED = new Color(0x80, 0x80, 0x80);
	private static final long MIN_SPAN = 50_000_000L;
	private static final long[] SPAN_BANDS = {
		50_000_000L, 100_000_000L, 200_000_000L, 500_000_000L,
		1_000_000_000L, 2_000_000_000L, 5_000_000_000L, 10_000_000_000L,
		20_000_000_000L, 50_000_000_000L, 100_000_000_000L
	};

	private List<WealthHistory.Point> series = Collections.emptyList();
	private long startMs;
	private long endMs;
	private boolean up = true;
	private int hoverIndex = -1;
	private String emptyMessage = "Collecting data…";

	WealthChart()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(100, 168));
		MouseAdapter ma = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				updateHover(e.getX());
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				updateHover(e.getX());
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (hoverIndex != -1)
				{
					hoverIndex = -1;
					repaint();
				}
			}
		};
		addMouseListener(ma);
		addMouseMotionListener(ma);
	}

	/** Hand the chart a new series and window. The series must be ascending
	 *  by time and already downsampled. */
	void setSeries(List<WealthHistory.Point> s, long startMs, long endMs)
	{
		this.series = (s == null) ? Collections.emptyList() : s;
		this.startMs = startMs;
		this.endMs = endMs;
		this.hoverIndex = -1;
		if (this.series.size() >= 2)
		{
			this.up = this.series.get(this.series.size() - 1).v >= this.series.get(0).v;
		}
		repaint();
	}

	void setEmptyMessage(String m)
	{
		this.emptyMessage = m;
		repaint();
	}

	private Insets plotInsets()
	{
		return new Insets(8, 6, 18, 6);
	}

	private void updateHover(int mx)
	{
		if (series.size() < 2)
		{
			return;
		}
		Insets in = plotInsets();
		int pw = getWidth() - in.left - in.right;
		if (pw <= 0)
		{
			return;
		}
		long span = Math.max(1L, endMs - startMs);
		int best = -1;
		double bestDx = Double.MAX_VALUE;
		for (int i = 0; i < series.size(); i++)
		{
			double px = in.left + (series.get(i).t - startMs) / (double) span * pw;
			double dx = Math.abs(px - mx);
			if (dx < bestDx)
			{
				bestDx = dx;
				best = i;
			}
		}
		if (best != hoverIndex)
		{
			hoverIndex = best;
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		super.paintComponent(g0);
		Graphics2D g = (Graphics2D) g0.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int w = getWidth();
		int h = getHeight();
		Insets in = plotInsets();
		int px0 = in.left;
		int py0 = in.top;
		int pw = w - in.left - in.right;
		int ph = h - in.top - in.bottom;

		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();

		if (series.isEmpty() || pw <= 0 || ph <= 0)
		{
			g.setColor(MUTED);
			int tw = fm.stringWidth(emptyMessage);
			g.drawString(emptyMessage, Math.max(0, (w - tw) / 2), h / 2);
			g.dispose();
			return;
		}

		long minV = Long.MAX_VALUE;
		long maxV = Long.MIN_VALUE;
		for (WealthHistory.Point p : series)
		{
			minV = Math.min(minV, p.v);
			maxV = Math.max(maxV, p.v);
		}
		// Give a single flat value some breathing room so it sits mid-plot.
		// Y-axis: keep a minimum visible range so a few-hundred-k wiggle on a big
		// total doesn't look like a 100% swing, and only widen to a "nice" band
		// (50M, 100M, 200M, 500M, 1B, 2B, ...) when the day's range actually grows.
		long dataRange = Math.max(0L, maxV - minV);
		long vSpan = niceSpan(Math.max(MIN_SPAN, dataRange));
		double center = (minV + maxV) / 2.0;
		double lo = Math.max(0.0, center - vSpan / 2.0);
		double hi = lo + vSpan;
		long span = Math.max(1L, endMs - startMs);

		Color line = up ? UP : DOWN;

		// y-axis reference lines + value labels (drawn behind the series)
		drawYAxis(g, fm, minV, maxV, lo, hi, px0, py0, pw, ph, w);

		// time-axis labels
		g.setColor(MUTED);
		SimpleDateFormat fmt = axisFormat(span);
		int labels = Math.max(2, Math.min(5, pw / 55));
		for (int i = 0; i < labels; i++)
		{
			long t = startMs + (long) ((double) i / (labels - 1) * span);
			String txt = fmt.format(new Date(t));
			int tw = fm.stringWidth(txt);
			double x = px0 + (t - startMs) / (double) span * pw;
			int tx = (int) Math.round(x - tw / 2.0);
			tx = Math.max(0, Math.min(w - tw, tx));
			g.drawString(txt, tx, h - 5);
		}

		double[] xs = new double[series.size()];
		double[] ys = new double[series.size()];
		for (int i = 0; i < series.size(); i++)
		{
			WealthHistory.Point p = series.get(i);
			xs[i] = px0 + (p.t - startMs) / (double) span * pw;
			ys[i] = py0 + (1.0 - (p.v - lo) / (hi - lo)) * ph;
		}

		if (series.size() == 1)
		{
			// Just populated: a small green marker + stub line, not a spike.
			int cx = (int) Math.round(xs[0]);
			int cy = (int) Math.round(ys[0]);
			g.setColor(line);
			g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(cx - 7, cy, cx + 7, cy);
			g.fillOval(cx - 3, cy - 3, 6, 6);
			g.dispose();
			return;
		}

		GeneralPath path = new GeneralPath();
		for (int i = 0; i < series.size(); i++)
		{
			if (i == 0)
			{
				path.moveTo(xs[i], ys[i]);
			}
			else
			{
				path.lineTo(xs[i], ys[i]);
			}
		}

		// subtle fill so the chart reads as a line, not a filled bar
		GeneralPath fill = new GeneralPath(path);
		fill.lineTo(xs[xs.length - 1], py0 + ph);
		fill.lineTo(xs[0], py0 + ph);
		fill.closePath();
		g.setPaint(new GradientPaint(
			0, py0, new Color(line.getRed(), line.getGreen(), line.getBlue(), 38),
			0, py0 + ph, new Color(line.getRed(), line.getGreen(), line.getBlue(), 0)));
		g.fill(fill);

		g.setColor(line);
		g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(path);

		if (hoverIndex >= 0 && hoverIndex < series.size())
		{
			int hx = (int) Math.round(xs[hoverIndex]);
			int hy = (int) Math.round(ys[hoverIndex]);
			g.setColor(new Color(0xAA, 0xAA, 0xAA, 110));
			g.setStroke(new BasicStroke(1f));
			g.drawLine(hx, py0, hx, py0 + ph);
			g.setColor(line);
			g.fillOval(hx - 3, hy - 3, 6, 6);

			WealthHistory.Point p = series.get(hoverIndex);
			drawReadout(g, WealthPanel.formatGp(p.v),
				sdf("MMM d, HH:mm 'UTC'").format(new Date(p.t)), hx, py0, w);
		}

		g.dispose();
	}

	private void drawYAxis(Graphics2D g, FontMetrics fm, long minV, long maxV,
						   double lo, double hi, int px0, int py0, int pw, int ph, int w)
	{
		long[] vals = {(long) hi, (long) ((lo + hi) / 2.0), (long) lo};
		for (long v : vals)
		{
			int y = (int) Math.round(py0 + (1.0 - (v - lo) / (hi - lo)) * ph);
			g.setColor(new Color(0x55, 0x55, 0x55, 70));
			g.drawLine(px0, y, px0 + pw, y);

			String txt = WealthPanel.formatGp(v);
			int tw = fm.stringWidth(txt);
			int ly = y - 2;
			if (ly < py0 + fm.getAscent())
			{
				ly = py0 + fm.getAscent();
			}
			g.setColor(new Color(0x9A, 0x9A, 0x9A));
			g.drawString(txt, w - tw - 1, ly);
		}
	}

	private void drawReadout(Graphics2D g, String value, String when, int anchorX, int top, int w)
	{
		FontMetrics fm = g.getFontMetrics();
		int pad = 4;
		int boxW = Math.max(fm.stringWidth(value), fm.stringWidth(when)) + pad * 2;
		int boxH = fm.getHeight() * 2 + pad * 2;
		int x = anchorX + 8;
		if (x + boxW > w)
		{
			x = anchorX - 8 - boxW;
		}
		x = Math.max(0, x);
		int y = top + 2;
		g.setColor(new Color(0x1A, 0x1A, 0x1A, 235));
		g.fillRoundRect(x, y, boxW, boxH, 6, 6);
		g.setColor(new Color(0x55, 0x55, 0x55));
		g.drawRoundRect(x, y, boxW, boxH, 6, 6);
		g.setColor(up ? UP : DOWN);
		g.drawString(value, x + pad, y + pad + fm.getAscent());
		g.setColor(new Color(0xBB, 0xBB, 0xBB));
		g.drawString(when, x + pad, y + pad + fm.getAscent() + fm.getHeight());
	}

	private static SimpleDateFormat sdf(String pattern)
	{
		SimpleDateFormat f = new SimpleDateFormat(pattern);
		f.setTimeZone(TimeZone.getTimeZone("UTC"));
		return f;
	}

	private static long niceSpan(long required)
	{
		for (long b : SPAN_BANDS)
		{
			if (b >= required)
			{
				return b;
			}
		}
		long s = SPAN_BANDS[SPAN_BANDS.length - 1];
		while (s < required)
		{
			s *= 2L;
		}
		return s;
	}

	private static SimpleDateFormat axisFormat(long spanMs)
	{
		long day = 86_400_000L;
		if (spanMs <= 2 * day)
		{
			return sdf("HH:mm");
		}
		if (spanMs <= 60 * day)
		{
			return sdf("MMM d");
		}
		if (spanMs <= 730 * day)
		{
			return sdf("MMM ''yy");
		}
		return sdf("yyyy");
	}
}

/*
 * Persistent Bank — RuneLite plugin
 *
 * Append-only per-account wealth history. Each time the plugin writes a
 * snapshot it appends one point (epochMs,valueGp) to
 * <snapshotDir>/history/<accountHash>.csv. Crucially, the value is whatever
 * the account was worth AT THAT MOMENT, priced with the GE prices that were
 * live then — so the series reflects real historical wealth, including price
 * movement, not a re-pricing of today's holdings against old dates.
 *
 * CSV (not JSON) on purpose: the file is hot-path append-only and can grow to
 * thousands of lines; two longs per line keeps it tiny and trivially parsed.
 */
package com.persistentbank;

import java.io.IOException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

final class WealthHistory
{
	private WealthHistory() { }

	/** One observation: total value {@code v} (gp) at wall-clock {@code t} (epoch ms). */
	static final class Point
	{
		final long t;
		final long v;

		Point(long t, long v)
		{
			this.t = t;
			this.v = v;
		}
	}

	private static Path historyDir(Path snapshotDir)
	{
		return snapshotDir.resolve("history");
	}

	/** Append one point for an account. Best-effort; never throws. */
	static void append(Path snapshotDir, long accountHash, long t, long v)
	{
		if (snapshotDir == null)
		{
			return;
		}
		try
		{
			Path d = historyDir(snapshotDir);
			Files.createDirectories(d);
			Path f = d.resolve(accountHash + ".csv");
			Files.writeString(f, t + "," + v + "\n",
				StandardOpenOption.CREATE, StandardOpenOption.APPEND);
		}
		catch (Exception ignored)
		{
			// History is non-critical; losing a point must never disrupt a write.
		}
	}

	/** Load all points for one account, ascending by time. Never throws;
	 *  returns empty on any error and skips malformed lines. */
	static List<Point> load(Path snapshotDir, long accountHash)
	{
		List<Point> out = new ArrayList<>();
		if (snapshotDir == null)
		{
			return out;
		}
		Path f = historyDir(snapshotDir).resolve(accountHash + ".csv");
		if (!Files.isRegularFile(f))
		{
			return out;
		}
		try
		{
			for (String line : Files.readAllLines(f))
			{
				int comma = line.indexOf(',');
				if (comma <= 0)
				{
					continue;
				}
				try
				{
					long t = Long.parseLong(line.substring(0, comma).trim());
					long v = Long.parseLong(line.substring(comma + 1).trim());
					if (v > 0)
					{
						out.add(new Point(t, v));
					}
				}
				catch (NumberFormatException ignored)
				{
					// skip junk line
				}
			}
		}
		catch (IOException ignored)
		{
			// unreadable file — return whatever parsed
		}
		out.sort((a, b) -> Long.compare(a.t, b.t));
		return out;
	}

	/** Value of one account at time {@code t}: the last observation at or
	 *  before {@code t} (forward-fill). Returns 0 if the account had no data
	 *  yet at that time. {@code pts} must be ascending by time. */
	private static long valueAt(List<Point> pts, long t)
	{
		int lo = 0, hi = pts.size() - 1, ans = -1;
		while (lo <= hi)
		{
			int mid = (lo + hi) >>> 1;
			if (pts.get(mid).t <= t)
			{
				ans = mid;
				lo = mid + 1;
			}
			else
			{
				hi = mid - 1;
			}
		}
		// Backward-fill: before an account's first record, assume its earliest
		// known value (wealth doesn't appear from nothing) so a combined total
		// never ramps up from zero as accounts are captured at different times.
		return pts.get(ans < 0 ? 0 : ans).v;
	}

	/** Build the summed series for {@code selected} accounts across
	 *  [{@code startMs}, {@code nowMs}]. Each account is forward-filled so the
	 *  combined total is correct even though accounts update at different
	 *  times. The line begins at {@code startMs} when there is earlier data to
	 *  carry forward, otherwise at the first real point inside the window.
	 *  Always terminates at {@code nowMs} with the current sum. */
	static List<Point> buildCombined(java.util.Map<Long, List<Point>> histories,
									 Set<Long> selected, long startMs, long nowMs)
	{
		TreeSet<Long> inWindow = new TreeSet<>();
		boolean anyBefore = false;
		for (Long h : selected)
		{
			List<Point> pts = histories.get(h);
			if (pts == null)
			{
				continue;
			}
			for (Point p : pts)
			{
				if (p.t < startMs)
				{
					anyBefore = true;
				}
				else if (p.t <= nowMs)
				{
					inWindow.add(p.t);
				}
			}
		}

		List<Point> out = new ArrayList<>();
		if (inWindow.isEmpty() && !anyBefore)
		{
			return out; // no data in or before the window
		}

		long effStart = anyBefore ? startMs : inWindow.first();

		TreeSet<Long> timeline = new TreeSet<>(inWindow);
		timeline.add(effStart);
		timeline.add(nowMs);

		for (Long t : timeline)
		{
			if (t < effStart || t > nowMs)
			{
				continue;
			}
			long sum = 0L;
			for (Long h : selected)
			{
				List<Point> pts = histories.get(h);
				if (pts != null && !pts.isEmpty())
				{
					sum += valueAt(pts, t);
				}
			}
			out.add(new Point(t, sum));
		}
		return out;
	}

	/** Reduce a series to at most {@code maxPoints} by uniform index bucketing,
	 *  always keeping the first and last point. Keeps long windows (1Y / All)
	 *  cheap to draw without distorting the shape. */
	/** Delete all saved history for every account. The live snapshots (current
	 *  totals) are untouched; only the chart's time-series is wiped. Best-effort;
	 *  never throws. */
	static void clear(Path snapshotDir)
	{
		if (snapshotDir == null)
		{
			return;
		}
		Path d = historyDir(snapshotDir);
		if (!Files.isDirectory(d))
		{
			return;
		}
		try (DirectoryStream<Path> stream = Files.newDirectoryStream(d, "*.csv"))
		{
			for (Path p : stream)
			{
				try
				{
					Files.deleteIfExists(p);
				}
				catch (Exception ignored)
				{
					// skip a file we can't remove
				}
			}
		}
		catch (Exception ignored)
		{
			// directory-level failure — nothing more to do
		}
	}

	/** Drop single downward spikes that immediately recover — a point well below
	 *  both of its neighbours. On a wealth line that's a capture artifact (a write
	 *  that briefly missed a section), never a real change; a genuine drop keeps a
	 *  low neighbour and is preserved. */
	static List<Point> filterSpikes(List<Point> in)
	{
		int n = in.size();
		if (n < 3)
		{
			return in;
		}
		List<Point> out = new ArrayList<>(n);
		out.add(in.get(0));
		for (int i = 1; i < n - 1; i++)
		{
			long cur = in.get(i).v;
			long lowNeighbour = Math.min(in.get(i - 1).v, in.get(i + 1).v);
			if (cur < lowNeighbour * 85L / 100L)
			{
				continue; // dip-and-recover artifact — skip
			}
			out.add(in.get(i));
		}
		out.add(in.get(n - 1));
		return out;
	}

	static List<Point> downsample(List<Point> in, int maxPoints)
	{
		int n = in.size();
		if (maxPoints < 2 || n <= maxPoints)
		{
			return in;
		}
		List<Point> out = new ArrayList<>(maxPoints);
		out.add(in.get(0));
		double step = (double) (n - 1) / (maxPoints - 1);
		for (int i = 1; i < maxPoints - 1; i++)
		{
			out.add(in.get((int) Math.round(i * step)));
		}
		out.add(in.get(n - 1));
		return out;
	}
}

/*
